import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  CircularProgress,
  Alert,
} from '@mui/material';

interface Worker {
  worker_id: string;
  status: string;
  current_job?: string;
  jobs_completed: number;
  jobs_failed: number;
  last_seen: string;
}

interface QueueStatus {
  queue: {
    queued: number;
    processing: number;
    paused: number;
    completed: number;
    failed: number;
  };
  workers?: Worker[];
}

export default function ValidationWorkers() {
  const [data, setData] = useState<QueueStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchStatus = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch('/validation/queue/status');
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const result = await response.json();
      setData(result);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStatus();
    const interval = setInterval(fetchStatus, 10000);
    return () => clearInterval(interval);
  }, []);

  if (loading && !data) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ mb: 3 }}>
        {error}
      </Alert>
    );
  }

  if (!data) return null;

  return (
    <Box>
      <Box sx={{ mb: 3 }}>
        <Typography variant="h5" fontWeight="600" gutterBottom>
          Workers
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Validation worker status and metrics
        </Typography>
      </Box>

      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography variant="h6" fontWeight="600" gutterBottom>
          Queue Overview
        </Typography>
        <Box sx={{ display: 'flex', gap: 3, mt: 2, flexWrap: 'wrap' }}>
          <Box>
            <Typography variant="body2" color="text.secondary">Queued</Typography>
            <Typography variant="h4" fontWeight="bold" color="info.main">
              {data.queue.queued.toLocaleString()}
            </Typography>
          </Box>
          <Box>
            <Typography variant="body2" color="text.secondary">Processing</Typography>
            <Typography variant="h4" fontWeight="bold" color="warning.main">
              {data.queue.processing.toLocaleString()}
            </Typography>
          </Box>
          <Box>
            <Typography variant="body2" color="text.secondary">Completed</Typography>
            <Typography variant="h4" fontWeight="bold" color="success.main">
              {data.queue.completed.toLocaleString()}
            </Typography>
          </Box>
          <Box>
            <Typography variant="body2" color="text.secondary">Failed</Typography>
            <Typography variant="h4" fontWeight="bold" color="error.main">
              {data.queue.failed.toLocaleString()}
            </Typography>
          </Box>
        </Box>
      </Paper>

      <Paper sx={{ p: 3 }}>
        <Typography variant="h6" fontWeight="600" gutterBottom>
          Worker Status
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Workers are managed by the validation service
        </Typography>
        <Alert severity="info" sx={{ mt: 2 }}>
          Worker pool is automatically scaled based on queue depth. Current processing: {data.queue.processing.toLocaleString()} items.
        </Alert>
      </Paper>
    </Box>
  );
}
